import torch
import torch.nn as nn
import math
from torch.utils.cpp_extension import load_inline

conv_transpose2d_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv_transpose2d_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    float* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int H_in, int W_in,
    int H_out, int W_out,
    int kernel_h, int kernel_w,
    int stride_h, int stride_w,
    int padding_h, int padding_w,
    int groups,
    bool has_bias
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= batch_size * out_channels * H_out * W_out) return;

    int n = idx / (out_channels * H_out * W_out);
    int oc = (idx / (H_out * W_out)) % out_channels;
    int oh = (idx / W_out) % H_out;
    int ow = idx % W_out;

    int group_size = out_channels / groups;
    int group_idx = oc / group_size;
    int in_channels_per_group = in_channels / groups;

    float sum = 0.0f;

    for (int kh = 0; kh < kernel_h; ++kh) {
        for (int kw = 0; kw < kernel_w; ++kw) {
            int ih = (oh - kh + padding_h) / stride_h;
            int iw = (ow - kw + padding_w) / stride_w;

            if ((oh - kh + padding_h) % stride_h != 0) continue;
            if ((ow - kw + padding_w) % stride_w != 0) continue;
            if (ih < 0 || ih >= H_in || iw < 0 || iw >= W_in) continue;

            for (int ic = 0; ic < in_channels_per_group; ++ic) {
                int input_idx = n * in_channels * H_in * W_in
                              + (group_idx * in_channels_per_group + ic) * H_in * W_in
                              + ih * W_in
                              + iw;
                float input_val = input[input_idx];

                int oc_in_group = oc % group_size;
                int weight_idx = ic * (group_size * kernel_h * kernel_w)
                               + oc_in_group * (kernel_h * kernel_w)
                               + kh * kernel_w
                               + kw;
                float weight_val = weight[weight_idx];

                sum += input_val * weight_val;
            }
        }
    }

    if (has_bias) sum += bias[oc];
    output[idx] = sum;
}

torch::Tensor conv_transpose2d_cuda_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride_h, int stride_w,
    int padding_h, int padding_w,
    int output_padding_h, int output_padding_w,
    int groups,
    bool has_bias
) {
    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int H_in = input.size(2);
    int W_in = input.size(3);

    int out_channels = weight.size(1) * groups;
    int kernel_h = weight.size(2);
    int kernel_w = weight.size(3);

    int H_out = (H_in - 1) * stride_h - 2 * padding_h + kernel_h + output_padding_h;
    int W_out = (W_in - 1) * stride_w - 2 * padding_w + kernel_w + output_padding_w;

    auto output = torch::zeros({batch_size, out_channels, H_out, W_out}, input.options());
    int total_elements = batch_size * out_channels * H_out * W_out;

    const int block_size = 256;
    int grid_size = (total_elements + block_size - 1) / block_size;

    conv_transpose2d_kernel<<<grid_size, block_size>>>(
        input.contiguous().data_ptr<float>(),
        weight.contiguous().data_ptr<float>(),
        has_bias ? bias.contiguous().data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size, in_channels, out_channels,
        H_in, W_in, H_out, W_out,
        kernel_h, kernel_w,
        stride_h, stride_w,
        padding_h, padding_w,
        groups,
        has_bias
    );

    return output;
}
"""

conv_transpose2d_cpp_source = """
torch::Tensor conv_transpose2d_cuda_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride_h, int stride_w,
    int padding_h, int padding_w,
    int output_padding_h, int output_padding_w,
    int groups,
    bool has_bias
);
"""

conv_transpose2d_ext = load_inline(
    name="conv_transpose2d_ext",
    cpp_sources=conv_transpose2d_cpp_source,
    cuda_sources=conv_transpose2d_source,
    functions=["conv_transpose2d_cuda_forward"],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: int = 1, padding: int = 0, output_padding: int = 0, groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = (stride, stride) if isinstance(stride, int) else stride
        self.padding = (padding, padding) if isinstance(padding, int) else padding
        self.output_padding = (output_padding, output_padding) if isinstance(output_padding, int) else output_padding
        self.groups = groups
        self.has_bias = bias

        kernel_h, kernel_w = kernel_size
        self.weight = nn.Parameter(torch.Tensor(
            in_channels,
            out_channels // groups,
            kernel_h,
            kernel_w
        ))
        if bias:
            self.bias = nn.Parameter(torch.Tensor(out_channels))
        else:
            self.register_parameter('bias', None)

        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / math.sqrt(fan_in)
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return conv_transpose2d_ext.conv_transpose2d_cuda_forward(
            x, self.weight, self.bias,
            self.stride[0], self.stride[1],
            self.padding[0], self.padding[1],
            self.output_padding[0], self.output_padding[1],
            self.groups,
            self.has_bias
        )
